mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import { decide } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g2-3/bot.mjs';
import assert from 'node:assert/strict';

const base = { userId: 'u1', category: 'marketing', timezone: 'Europe/Istanbul', quietStart: '22:00', quietEnd: '07:30' };
// 2026-10-23 12:00 in Istanbul (UTC+3) = 09:00Z
const noon = new Date('2026-10-23T09:00:00Z');

// Daily cap: 3 allowed, 4th blocked, same local day
for (let i = 0; i < 3; i++) assert.deepEqual(decide({ ...base }, noon), { send: true, rule: null });
assert.deepEqual(decide({ ...base }, noon), { send: false, rule: 'daily-cap' });

// Transactional passes even when capped, and during quiet hours
assert.deepEqual(decide({ ...base, category: 'transactional' }, noon), { send: true, rule: null });
const night = new Date('2026-10-23T22:30:00Z'); // 01:30 Istanbul
assert.deepEqual(decide({ ...base, category: 'transactional', userId: 'u9' }, night), { send: true, rule: null });

// Quiet hours (wrapping window), local time: 01:30 in Istanbul is quiet
assert.deepEqual(decide({ ...base, userId: 'q1' }, night), { send: false, rule: 'quiet-hours' });
// 07:30 local is end (exclusive) -> allowed. 07:30 Istanbul = 04:30Z
assert.deepEqual(decide({ ...base, userId: 'q2' }, new Date('2026-10-23T04:30:00Z')), { send: true, rule: null });
// 06:59 local -> quiet
assert.deepEqual(decide({ ...base, userId: 'q3' }, new Date('2026-10-23T03:59:00Z')), { send: false, rule: 'quiet-hours' });
// 22:00 local -> quiet (start inclusive)
assert.deepEqual(decide({ ...base, userId: 'q4' }, new Date('2026-10-23T19:00:00Z')), { send: false, rule: 'quiet-hours' });

// Quiet-blocked pushes are not counted toward the cap
for (let i = 0; i < 5; i++) decide({ ...base, userId: 'q5' }, night);
assert.deepEqual(decide({ ...base, userId: 'q5' }, noon), { send: true, rule: null });

// Non-wrapping window
const day = { userId: 'd1', category: 'marketing', timezone: 'UTC', quietStart: '13:00', quietEnd: '14:00' };
assert.deepEqual(decide(day, new Date('2026-10-23T13:30:00Z')), { send: false, rule: 'quiet-hours' });
assert.deepEqual(decide({ ...day, userId: 'd2' }, new Date('2026-10-23T14:00:00Z')), { send: true, rule: null });

// Equal start/end = no window
assert.deepEqual(decide({ ...base, userId: 'e1', quietStart: '00:00', quietEnd: '00:00' }, night), { send: true, rule: null });

// Customer's local day, not server/UTC day: 23:30 UTC Oct 23 = 02:30 Oct 24 in Istanbul.
// Cap used on Oct 23 local must reset on Oct 24 local.
const c = { userId: 'day', category: 'marketing', timezone: 'Europe/Istanbul', quietStart: '00:00', quietEnd: '00:00' };
for (let i = 0; i < 3; i++) decide(c, new Date('2026-10-23T10:00:00Z')); // Oct 23 13:00 Istanbul
assert.equal(decide(c, new Date('2026-10-23T20:00:00Z')).rule, 'daily-cap'); // Oct 23 23:00 Istanbul
assert.deepEqual(decide(c, new Date('2026-10-23T21:30:00Z')), { send: true, rule: null }); // Oct 24 00:30 Istanbul
// Another zone: Pacific, same instant is still Oct 23 locally -> still capped, cap is per customer zone
const la = { userId: 'la', category: 'marketing', timezone: 'America/Los_Angeles', quietStart: '00:00', quietEnd: '00:00' };
for (let i = 0; i < 3; i++) decide(la, new Date('2026-10-23T10:00:00Z')); // Oct 23 03:00 LA
assert.equal(decide(la, new Date('2026-10-23T20:00:00Z')).rule, 'daily-cap'); // Oct 23 13:00 LA

// DST: Europe/Berlin fall-back 2026-10-25 — quiet window still evaluated on local clock
const berlin = { userId: 'b', category: 'marketing', timezone: 'Europe/Berlin', quietStart: '02:30', quietEnd: '03:30' };
// 02:45 Berlin on Oct 25 (CEST, UTC+2 before fall-back at 03:00 local) = 00:45Z
assert.deepEqual(decide(berlin, new Date('2026-10-25T00:45:00Z')), { send: false, rule: 'quiet-hours' });

// Validation errors
assert.throws(() => decide({ ...base, timezone: 'Mars/Olympus' }, noon), TypeError);
assert.throws(() => decide({ ...base, quietStart: '24:00' }, noon), TypeError);
assert.throws(() => decide({ ...base, quietEnd: '7:30' }, noon), TypeError);
assert.throws(() => decide({ ...base, category: 'promo' }, noon), TypeError);
assert.throws(() => decide({ ...base }, new Date('nope')), TypeError);
assert.throws(() => decide(null, noon), TypeError);

console.log('all checks passed');
EOF
